package com.jobpilot.job;import com.jobpilot.user.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="job_offers",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","external_id"}))public class JobOffer{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="user_id")private User user;@Column(nullable=false)private String title;@Column(nullable=false)private String company;private String location;private boolean remote;private BigDecimal salaryMin;private BigDecimal salaryMax;@Column(length=1000)private String description;@Column(length=700)private String url;private String source="MANUAL";@Column(name="external_id")private String externalId;private LocalDateTime publishedAt;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getCompany(){return company;}public void setCompany(String v){company=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public boolean isRemote(){return remote;}public void setRemote(boolean v){remote=v;}public BigDecimal getSalaryMin(){return salaryMin;}public void setSalaryMin(BigDecimal v){salaryMin=v;}public BigDecimal getSalaryMax(){return salaryMax;}public void setSalaryMax(BigDecimal v){salaryMax=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getUrl(){return url;}public void setUrl(String v){url=v;}public String getSource(){return source;}public void setSource(String v){source=v;}public String getExternalId(){return externalId;}public void setExternalId(String v){externalId=v;}public LocalDateTime getPublishedAt(){return publishedAt;}public void setPublishedAt(LocalDateTime v){publishedAt=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
